import { Component } from "@angular/core";
import { FormGroup } from "@angular/forms";

@Component({
  selector: "app-registration-form",
  templateUrl: "./registration-form.component.html",
  styleUrls: ["./registration-form.component.scss"],
})
export class RegistrationFormComponent {
  registrationForm!: FormGroup;
  // Use the names `name`, `email`, `password` for the form controls.

  constructor(private fb: FormBuilder) {
    this.createForm();
  }

  // Initialize the form with validation rules
  createForm() {
    this.registrationForm = this.fb.group({
      name: [
        "", // Initial value
        [
          Validators.required, // Field is required
          Validators.minLength(6), // Minimum length is 6 characters
        ],
      ],
      email: [
        "", // Initial value
        [
          Validators.required, // Field is required
          // Attach custom email validator via directive
        ],
      ],
      password: [
        "", // Initial value
        [
          Validators.required, // Field is required
        ],
      ],
    });
  }

  // Handle form submission
  onSubmit() {
    if (this.registrationForm.valid) {
      console.log("Form Submitted Successfully:", this.registrationForm.value);
    } else {
      // Automatically mark all controls as touched to trigger errors
      this.registrationForm.markAllAsTouched();
    }
  }
}
